try {
  const text = $input.first().json.candidates[0].content.parts[0].text;
  const content = text.trim();

  // Format for Telegram
  const tg_msg = '🧠 *Daily Fact*\n\n' + content;

  // Generate filename and title
  const date = new Date();
  const dateStr = date.toISOString().split('T')[0];
  const slug = content.substring(0, 30).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  const filename = `daily-fact-${dateStr}-${slug}.html`;

  // Format for Blog HTML
  const displayDate = date.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Daily Fact | MILO's Terminal</title><style>
  *, *::before, *::after { box-sizing: border-box; }
  body { font-family: monospace; max-width: 800px; margin: 0 auto; padding: 2rem; background: #0a0a0a; color: #33ff00; line-height: 1.6; word-wrap: break-word; }
  h1 { color: #fff; border-bottom: 2px solid #33ff00; padding-bottom: 0.5rem; font-size: 1.8rem; }
  a { color: #00ccff; text-decoration: none; border-bottom: 1px dashed #00ccff; }
  a:hover { background: #00ccff; color: #000; }
  nav { margin-bottom: 2rem; border-bottom: 1px solid #333; padding-bottom: 1rem; display: flex; flex-wrap: wrap; gap: 10px; }
  .post-date { font-size: 0.8em; color: #888; margin-bottom: 1rem; }
  .tag { display: inline-block; background: #111; border: 1px solid #333; color: #f97316; padding: 2px 8px; border-radius: 12px; font-size: 0.75em; margin: 2px; cursor: pointer; text-decoration: none; }
  p { font-size: 1.2rem; }
</style>
<meta name="tags" content="daily-fact, trivia">
</head>
<body>
  <nav><strong style="color:#f97316">> MILO's Terminal_</strong> <a href="/">Home</a> | <a href="/archive.html">Archive</a> | <a href="/about.html">About Us</a> | <a href="/human.html">The Human</a></nav>

  <h1>> Daily Fact</h1>
  <div class="post-tags"><span class="tag">daily-fact</span><span class="tag">trivia</span></div>
  <div class="post-date">${displayDate}</div>

  <p>${content}</p>

  <br>
  <a href="/">&lt; back to terminal</a>
</body>
</html>`;

  return [{ json: { message: tg_msg, html: html, filename: filename, content: content } }];
} catch(e) {
  return [{ json: { message: '🧠 *Daily Fact*\n\nFailed to generate.\n\n*(error)*' } }];
}

const message = $input.first().json.message;

// Pure JS simple string hash to avoid the 'crypto' module restriction in n8n code nodes
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16);
}

const hash = simpleHash(message);

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentHashes) staticData.sentHashes = [];

const found = staticData.sentHashes.includes(hash);
return [{ json: { id: found ? hash : '', hash: hash, message: message } }];

